(()=>{const data=window.HANZI_SITE_MESSAGES;const overrides={...data.hi};Object.assign(data.hi,{"Skip to content":"मुख्य सामग्री पर जाएँ","Previous screenshot":"पिछला स्क्रीनशॉट","Next screenshot":"अगला स्क्रीनशॉट","raccoon.app.labs@gmail.com":"raccoon.app.labs@gmail.com","Оферта":"सार्वजनिक प्रस्ताव","© 2026 Raccoon App Labs":"© 2026 Raccoon App Labs","Тарифы Plus":"Plus प्लान","Архив первой редакции от 16 октября 2026 года.":"16 अक्टूबर 2026 के प्रथम संस्करण का संग्रह।","Действующая редакция":"वर्तमान संस्करण","Предыдущая редакция:":"पिछला संस्करण:","8 октября 2026 года":"8 अक्टूबर 2026","Аккаунт и доступ":"खाता और पहुँच","Твои данные · понятные правила":"आपका डेटा · साफ़ नियम","Политика конфиденциальности":"गोपनीयता नीति","Содержание":"विषय-सूची","Кто обрабатывает":"डेटा कौन संसाधित करता है","Какие данные":"कौन-सा डेटा","Внешние сервисы":"बाहरी सेवाएँ","Сроки":"अवधियाँ","Удаление и права":"हटाना और अधिकार","1. Кто отвечает за данные":"1. डेटा का उत्तरदायी कौन है","Оператор: Покаместова Анастасия Максимовна, самозанятая (НПД), ИНН 695205887530, город Тверь.":"नियंत्रक: Anastasia Maksimovna Pokamestova, स्व-नियोजित (पेशेवर आय कर), कर पहचान संख्या 695205887530, Tver।","Raccoon App Labs — название разработчика.":"Raccoon App Labs डेवलपर का नाम है।","Контакт по вопросам данных:":"डेटा संबंधी संपर्क:",", телефон":", फ़ोन","Она не заменяет правила самостоятельных платёжных, почтовых и системных сервисов.":"यह स्वतंत्र भुगतान, ईमेल और सिस्टम सेवाओं के नियमों का विकल्प नहीं।","2. Какие данные и для чего":"2. कौन-सा डेटा और क्यों","Прогресс обучения":"अध्ययन प्रगति","Аккаунт и вход":"खाता और प्रवेश","Адрес электронной почты, случайный идентификатор аккаунта, подтверждение почты, даты запросов и проверки кода.":"ईमेल, यादृच्छिक खाता पहचान, ईमेल सत्यापन और कोड अनुरोध तथा जाँच की तारीखें।","На сервере хранятся хеши одноразовых кодов и токенов сессий.":"सर्वर एकबारगी कोड और सत्र टोकन के हैश रखता है।","Они нужны для входа, проверки владельца заказа и восстановления оплаченного доступа.":"इनसे प्रवेश, ऑर्डर स्वामी की जाँच और सशुल्क पहुँच की बहाली होती है।","Покупка и Plus":"खरीद और Plus","Почта аккаунта, номер и статус заказа, идентификаторы продукта и предложения, сумма и валюта, выбранный срок, даты создания и подтверждения платежа, версия принятой оферты, дата окончания доступа, сведения о возврате или споре.":"खाते का ईमेल, ऑर्डर संख्या और स्थिति, उत्पाद तथा प्रस्ताव पहचान, राशि, मुद्रा, अवधि, भुगतान बनाने और पुष्टि की तारीखें, स्वीकृत संस्करण, पहुँच समाप्ति और वापसी या विवाद विवरण।","Ссылка на оплату хранится для продолжения созданного заказа.":"बनाया ऑर्डर जारी रखने के लिए भुगतान लिंक रखा जाता है।","Безопасность и работа сайта":"सुरक्षा और वेबसाइट संचालन","IP-адрес и технические параметры соединения доступны инфраструктуре при обращении к ней.":"कनेक्ट करते समय अवसंरचना को IP और तकनीकी कनेक्शन विवरण उपलब्ध होते हैं।","Для ограничения запросов входа сервер приложения использует хеш IP-адреса и счётчики запросов.":"प्रवेश अनुरोध सीमित करने के लिए सर्वर IP हैश और अनुरोध गणक उपयोग करता है।","Это помогает предотвратить подбор кодов и массовые запросы.":"इससे कोड का अनुमान लगाने और सामूहिक अनुरोध रोकने में मदद मिलती है।","Обращение в поддержку":"सहायता अनुरोध","Твоя почта и содержание присланного обращения, включая добровольно приложенные файлы и сведения о заказе.":"आपका ईमेल और भेजा संदेश, स्वेच्छा से जुड़ी फ़ाइलों तथा ऑर्डर विवरण सहित।","Используем их, чтобы ответить, восстановить доступ или обработать возврат.":"इनका उपयोग उत्तर, पहुँच बहाली या धनवापसी के लिए होता है।","Не присылай реквизиты карты, банковские коды и пароль от почты.":"कार्ड विवरण, बैंक कोड या ईमेल पासवर्ड न भेजें।","Аналитика приложения":"ऐप विश्लेषण","MyTracker получает события запуска, сессий, переходов между экранами и выполнения упражнений, а также технические сведения SDK: версию приложения и системы, параметры устройства, сетевые и доступные устройству идентификаторы.":"MyTracker शुरुआत, सत्र, स्क्रीन बदलाव और अभ्यास घटनाएँ तथा SDK का तकनीकी डेटा पाता है: ऐप और सिस्टम संस्करण, उपकरण मापदंड, नेटवर्क और उपलब्ध उपकरण पहचान।","Реклама":"विज्ञापन","Yandex Mobile Ads использует технические данные устройства, соединения, рекламные идентификаторы и сведения о показах для работы рекламы и защиты от недействительного трафика.":"Yandex Mobile Ads विज्ञापन दिखाने और अमान्य ट्रैफ़िक रोकने के लिए उपकरण, कनेक्शन, विज्ञापन पहचान और दृश्य संबंधी तकनीकी डेटा उपयोग करता है।","Передача геолокации для рекламы отключена настройкой приложения.":"ऐप सेटिंग में विज्ञापन हेतु स्थान भेजना बंद है।","Персонализация управляется переключателем в настройках Hanzi Bloom; при выключенной персонализации техническая обработка для показа рекламы может сохраняться.":"Hanzi Bloom की सेटिंग से वैयक्तिकरण नियंत्रित होता है; बंद करने पर भी विज्ञापन दिखाने का तकनीकी प्रसंस्करण रह सकता है।","Голосовая и рукописная практика":"बोलने और लिखने का अभ्यास","Микрофон включается для выбранного тобой голосового упражнения после разрешения Android.":"चुने मौखिक अभ्यास के लिए Android अनुमति के बाद माइक्रोफ़ोन चालू होता है।","Системная служба распознавания речи может обрабатывать звук на своих серверах в зависимости от устройства и выбранного сервиса.":"सिस्टम की वाणी पहचान सेवा उपकरण और चुनी सेवा के अनुसार अपने सर्वर पर आवाज़ संसाधित कर सकती है।","Сервер аккаунта Hanzi Bloom аудиозаписи не получает.":"Hanzi Bloom खाता सर्वर को ऑडियो रिकॉर्डिंग नहीं मिलती।","Распознавание рукописных штрихов выполняется на устройстве; модели могут загружаться через сервис их поставщика.":"हस्तलिखित स्ट्रोक की पहचान उपकरण पर होती है; मॉडल आपूर्तिकर्ता की सेवा से डाउनलोड हो सकते हैं।","Категории пользователей: посетители сайта, пользователи приложения и аккаунта, покупатели Plus и обратившиеся в поддержку.":"उपयोगकर्ता वर्ग: वेबसाइट आगंतुक, ऐप और खाता उपयोगकर्ता, Plus खरीदार और सहायता से संपर्क करने वाले।","Специальные категории данных и биометрическая идентификация для аккаунта и покупки не используются.":"खाता या खरीद के लिए विशेष डेटा वर्ग और बायोमेट्रिक पहचान का उपयोग नहीं होता।","3. Основания и способы обработки":"3. प्रसंस्करण के आधार और तरीके","Почта, данные аккаунта и заказа нужны для действий по запросу пользователя и исполнения договора.":"ईमेल, खाता और ऑर्डर डेटा उपयोगकर्ता के अनुरोध और अनुबंध पूरा करने के लिए आवश्यक हैं।","Данные расчётов сохраняются также для обязательных требований закона.":"भुगतान रिकॉर्ड अनिवार्य कानूनी जरूरतों के लिए भी रखे जाते हैं।","Технические данные используются для безопасности и улучшения приложения при наличии применимого правового основания.":"उचित कानूनी आधार होने पर तकनीकी डेटा सुरक्षा और सुधार के लिए उपयोग होता है।","Когда необходимо согласие, оно должно оформляться отдельно; эта политика не является согласием на рассылку или на неограниченную передачу данных.":"आवश्यक सहमति अलग ली जाती है; यह नीति विज्ञापन या असीमित डेटा हस्तांतरण की सहमति नहीं।","Обработка автоматизированная, а при обращениях — также с участием оператора: сбор, хранение, проверка, использование, предоставление необходимым сервисам, исправление и удаление.":"प्रसंस्करण स्वचालित और अनुरोधों में मानव द्वारा भी होता है: संग्रह, भंडारण, जाँच, उपयोग, आवश्यक सेवाओं को देना, सुधार और हटाना।","Персональные данные аккаунта не публикуются и не продаются.":"व्यक्तिगत खाता डेटा प्रकाशित या बेचा नहीं जाता।","Почта входа используется для кодов и сообщений по услуге, а не для рекламной рассылки.":"प्रवेश ईमेल कोड और सेवा संदेशों के लिए है, विज्ञापन के लिए नहीं।","4. Где обрабатываются данные":"4. डेटा कहाँ संसाधित होता है","Google / Gmail.":"Google / Gmail।","Почта и код входа передаются почтовому сервису для доставки письма. Обращения поддержки обрабатываются в Gmail.":"ईमेल पहुँचाने के लिए पता और कोड मेल सेवा को दिए जाते हैं। सहायता अनुरोध Gmail में देखे जाते हैं।","Политика Google":"Google नीति","Политика Lava":"Lava नीति","Robokassa.":"Robokassa।","При выборе доступного российского способа оплаты данные заказа обрабатываются этим сервисом.":"उपलब्ध रूसी भुगतान विकल्प चुनने पर यह सेवा ऑर्डर डेटा संसाधित करती है।","Политика Robokassa":"Robokassa नीति","GitHub Pages.":"GitHub Pages।","Размещает публичные страницы сайта и получает технические данные посещений. База аккаунтов и заказов не размещается в репозитории.":"सार्वजनिक पेज होस्ट करता और तकनीकी विज़िट डेटा पाता है। खाता और ऑर्डर डेटाबेस रिपॉज़िटरी में नहीं है।","Политика GitHub":"GitHub नीति","MyTracker (VK) и Yandex Mobile Ads.":"MyTracker (VK) और Yandex Mobile Ads।","Получают данные аналитики и рекламы, описанные выше, в версиях приложения с этими SDK.":"इन SDK वाले संस्करणों में ऊपर वर्णित विश्लेषण और विज्ञापन डेटा मिलता है।","Политика MyTracker":"MyTracker नीति","политика Яндекса":"Yandex नीति","Google, GitHub, Lava и системная служба распознавания могут обрабатывать сведения за пределами России; Lava указывает Кипр как место нахождения своей компании.":"Google, GitHub, Lava और सिस्टम वाणी पहचान रूस के बाहर डेटा संसाधित कर सकते हैं; Lava अपनी कंपनी का स्थान साइप्रस बताता है।","Российское размещение базы аккаунтов не означает, что все перечисленные сервисы работают только в России.":"रूस में खाता डेटाबेस होने का अर्थ सभी सेवाओं का केवल रूस में चलना नहीं।","Международная передача требует самостоятельного применимого основания и соблюдения установленных законом процедур; публикация политики их не заменяет.":"अंतरराष्ट्रीय हस्तांतरण के लिए अलग कानूनी आधार और प्रक्रियाएँ चाहिए; नीति प्रकाशित करना उनका विकल्प नहीं।","5. Хранение в браузере и на устройстве":"5. ब्राउज़र और उपकरण भंडारण","На странице покупки не установлены рекламные или аналитические счётчики.":"खरीद पेज पर विज्ञापन या विश्लेषण ट्रैकर नहीं हैं।","Инфраструктура GitHub и страницы внешних платёжных сервисов имеют собственные правила технического хранения и cookie.":"GitHub अवसंरचना और बाहरी भुगतान पेज के अपने भंडारण और कुकी नियम हैं।","В приложении токен аккаунта хранится с шифрованием через Android Keystore и исключён из системной резервной копии.":"ऐप का खाता टोकन Android Keystore से एन्क्रिप्ट है और सिस्टम बैकअप में नहीं जाता।","6. Сроки и защита":"6. अवधि और सुरक्षा","Код входа действует 10 минут; сессия — до 30 дней и прекращается раньше после подтверждённого выхода.":"प्रवेश कोड 10 मिनट; सत्र अधिकतम 30 दिन रहता है और पुष्ट साइन आउट पर पहले समाप्त होता है।","Неподтверждённый аккаунт хранится до 24 часов.":"असत्यापित खाता अधिकतम 24 घंटे रखा जाता है।","Истечение срока исключает их использование; физическое удаление временных записей выполняется механизмом базы данных и может происходить позднее.":"समाप्ति पर उपयोग रुकता है; डेटाबेस अस्थायी रिकॉर्ड बाद में भौतिक रूप से हटा सकता है।","Аккаунт хранится для восстановления доступа, пока он нужен пользователю; удаление запрашивается по правилам следующего раздела.":"पहुँच बहाल करने के लिए जरूरत तक खाता रहता है; हटाने के नियम अगले अनुभाग में हैं।","Данные платежей и обращений сохраняются только на срок, необходимый для исполнения обязательств, возвратов, разрешения споров и обязательного учёта, затем удаляются или обезличиваются.":"भुगतान और अनुरोध डेटा अनुबंध, वापसी, विवाद और अनिवार्य लेखांकन के लिए जरूरी अवधि तक रहता है, फिर मिटता या अनाम किया जाता है।","Обязательные записи могут сохраняться после удаления аккаунта.":"अनिवार्य रिकॉर्ड खाता मिटने के बाद भी रह सकते हैं।","Соединение с сервером защищено HTTPS.":"सर्वर कनेक्शन HTTPS से सुरक्षित है।","Применяются ограничение запросов, проверка принадлежности заказа, контроль доступа к инфраструктуре и хранение хешей вместо открытых кодов и серверных токенов.":"अनुरोध सीमाएँ, ऑर्डर स्वामी सत्यापन, अवसंरचना पहुँच नियंत्रण और खुले कोड तथा टोकन के बजाय हैश उपयोग होते हैं।","Не передавай другим людям код входа.":"अपना प्रवेश कोड किसी को न दें।","Оплата и активация не подтверждаются одним только адресом страницы «успех»: сервер проверяет уведомление и сведения платёжного сервиса.":"केवल «सफलता» पेज का पता भुगतान या सक्रियण का प्रमाण नहीं; सर्वर सेवा की सूचना और विवरण जाँचता है।","7. Уточнение и удаление данных":"7. डेटा सुधारना और हटाना","Хочешь удалить аккаунт?":"खाता मिटाना चाहते हैं?","Напиши с почты аккаунта на":"खाते वाले ईमेल से लिखें","Можно запросить сведения об обработке своих данных, исправление, блокирование или удаление, а также отозвать согласие, если обработка основана на нём.":"अपने डेटा की जानकारी, सुधार, रोक या हटाने का अनुरोध और सहमति आधारित प्रसंस्करण की सहमति वापस ले सकते हैं।","Для защиты аккаунта оператор проверяет, что обращается его владелец.":"खाते की रक्षा हेतु नियंत्रक स्वामी की पहचान जाँचता है।","Карта, CVC и код входа для обращения не нужны.":"अनुरोध के लिए कार्ड, CVC या प्रवेश कोड नहीं चाहिए।","Если сохранить часть записей требует закон, сообщаем об этом при ответе.":"कानून कुछ रिकॉर्ड रखना माँगे तो उत्तर में बताया जाता है।","Обращения рассматриваются в применимые законные сроки.":"अनुरोध लागू कानूनी समयसीमा में देखे जाते हैं।","оферте":"प्रस्ताव","Удаление локального прогресса выполняется через настройки Android или приложения.":"स्थानीय प्रगति Android या ऐप सेटिंग से हटती है।","Запросы к самостоятельным внешним сервисам можно направлять им по указанным выше политикам.":"स्वतंत्र बाहरी सेवाओं को ऊपर जुड़ी उनकी नीतियों के अनुसार अनुरोध भेज सकते हैं।","По вопросам защиты персональных данных можно обратиться к оператору, а также в уполномоченный орган — Роскомнадзор — или в суд.":"डेटा सुरक्षा के लिए नियंत्रक, अधिकृत प्राधिकरण Roskomnadzor या अदालत से संपर्क कर सकते हैं।","8. Дети и изменения политики":"8. बच्चे और नीति बदलाव","Аккаунт для покупки используется дееспособным покупателем; при необходимости покупку совершает законный представитель.":"खरीद खाता कानूनी रूप से सक्षम खरीदार उपयोग करता है; आवश्यकता पर कानूनी प्रतिनिधि खरीदता है।","В обращении о данных ребёнка представитель может связаться с оператором.":"प्रतिनिधि बच्चे के डेटा पर नियंत्रक से संपर्क कर सकता है।","Приложение не запрашивает дату рождения для покупки.":"खरीद के लिए जन्मतिथि नहीं माँगी जाती।","Новая редакция публикуется по этому адресу с датой изменения.":"नया संस्करण बदलाव की तारीख सहित इसी पते पर प्रकाशित होता है।","Если меняются цели или состав обработки, для которых необходимо отдельное согласие, обновление текста само по себе его не заменяет.":"अलग सहमति जरूरी होने वाले उद्देश्य या डेटा वर्ग बदलें तो पाठ अपडेट करना सहमति का विकल्प नहीं।","Поддержка":"सहायता","Какие данные используют Hanzi Bloom и Hanzi Keys: прогресс, аккаунт, оплата, аналитика и реклама. Как запросить удаление аккаунта.":"Hanzi Bloom और Hanzi Keys के डेटा: प्रगति, खाता, भुगतान, विश्लेषण और विज्ञापन। खाता हटाने का अनुरोध कैसे करें।","Конфиденциальность · Hanzi Bloom и Hanzi Keys":"गोपनीयता · Hanzi Bloom और Hanzi Keys","Hanzi":"Hanzi","Политика обработки персональных данных. Редакция от 16 октября 2026 года.":"व्यक्तिगत डेटा प्रसंस्करण नीति। 16 अक्टूबर 2026 का संस्करण।","Один аккаунт для Bloom и Keys.":"Bloom और Keys के लिए एक खाता।","Почта нужна для входа и восстановления общего Plus.":"ईमेल प्रवेश और साझा Plus बहाली के लिए है।","После первой подписки поддерживаемый прогресс сохраняется в аккаунте и после окончания оплаченного срока.":"पहली सदस्यता के बाद समर्थित प्रगति सशुल्क अवधि खत्म होने पर भी खाते में रहती है।","Данные карты вводятся у Робокассы.":"कार्ड विवरण Robokassa में डालते हैं।","Удаление аккаунта и облачных данных можно запросить в поддержку.":"सहायता से खाता और क्लाउड डेटा हटाने को कह सकते हैं।","Политика относится к Android-приложениям Hanzi Bloom и Hanzi Keys, их общему аккаунту Hanzi Plus и страницам этих приложений на raccoon-app-labs.github.io.":"नीति Android के Hanzi Bloom, Hanzi Keys, उनके साझा Hanzi Plus खाते और raccoon-app-labs.github.io के पेजों पर लागू है।","Прогресс и настройки сохраняются на устройстве.":"प्रगति और सेटिंग उपकरण पर रहती हैं।","Для подтверждённого аккаунта, хотя бы раз получившего производственную подписку Plus, поддерживаемый прогресс также синхронизируется с сервером.":"कम-से-कम एक बार उत्पादन Plus पाने वाले सत्यापित खाते में समर्थित प्रगति सर्वर से भी सिंक होती है।","Keys передаёт только ID изученных ключей; неизученные карточки и тексты каталога не копируются.":"Keys केवल सीखे मूल घटकों की ID भेजता है; अनसीखे कार्ड और कैटलॉग पाठ कॉपी नहीं होते।","Bloom передаёт ID и статусы изучаемых слов и иероглифов, ID завершённых уроков, последний урок, достигнутый уровень курса и лучшие результаты проверок глав.":"Bloom अध्ययन शब्दों और अक्षरों की ID तथा स्थिति, पूरे पाठों की ID, अंतिम पाठ, स्तर और अध्याय जाँच के सर्वोत्तम परिणाम भेजता है।","Облачные записи приложений раздельны и принадлежат аккаунту.":"हर ऐप के क्लाउड रिकॉर्ड अलग हैं और खाते के हैं।","Личные заметки, аудио, рисунки, полная история упражнений и локальные интервалы повторений в эту облачную копию не входят.":"इस क्लाउड प्रति में निजी नोट्स, ऑडियो, चित्र, पूरी अभ्यास-इतिहास और स्थानीय पुनरावृत्ति अंतराल नहीं हैं।","Нужны поддерживающая версия, вход и Интернет.":"समर्थित संस्करण, प्रवेश और इंटरनेट चाहिए।","Бесплатная неделя и тестовые платежи не включают облако.":"मुफ़्त सप्ताह और परीक्षण भुगतान क्लाउड नहीं खोलते।","Полный номер карты, CVC и банковские коды сервер Hanzi не получает.":"Hanzi सर्वर को पूरा कार्ड नंबर, CVC और बैंक कोड नहीं मिलते।","Неделя знакомства Keys":"Keys का परिचय सप्ताह","Случайный ключ установки хранится на устройстве; сервер использует его хеш, дату начала бесплатного периода и признак ранее предоставленного Plus.":"यादृच्छिक इंस्टॉल कुंजी उपकरण पर रहती है; सर्वर उसका हैश, मुफ़्त अवधि की शुरुआत और पहले Plus मिलने का संकेत उपयोग करता है।","При входе история периода связывается также с аккаунтом.":"प्रवेश पर अवधि का इतिहास खाते से भी जुड़ता है।","Это нужно для расчёта срока знакомства и проверки доступа, а не для идентификации по содержимому устройства.":"यह परिचय अवधि और पहुँच जाँचने के लिए है, उपकरण की सामग्री से पहचानने के लिए नहीं।","В пользовательские события приложений не добавляются текст поиска, свои слова, переводы, тексты историй, рукописные штрихи, почта аккаунта или токен входа.":"निजी ऐप घटनाओं में खोज, अपने शब्द, अनुवाद, कहानी, हस्तलिखित स्ट्रोक, ईमेल या टोकन नहीं जुड़ते।","Российская серверная инфраструктура Hanzi.":"Hanzi की रूसी सर्वर अवसंरचना।","Аккаунты российского региона, подписки, заказы и поддерживаемый облачный прогресс обрабатываются через api1.hanzibloom.ru в российском серверном хранилище.":"रूसी क्षेत्र के खाते, सदस्यताएँ, ऑर्डर और समर्थित क्लाउड प्रगति api1.hanzibloom.ru के रूसी भंडारण में संसाधित होते हैं।","Аккаунты и прогресс разных пользователей разделены.":"अलग उपयोगकर्ताओं के खाते और प्रगति अलग हैं।","База не размещается в публичном репозитории GitHub.":"डेटाबेस सार्वजनिक GitHub रिपॉज़िटरी में नहीं है।","Прежнее размещение Yandex Cloud описано в архивной редакции политики.":"पुरानी Yandex Cloud होस्टिंग संग्रहित नीति में बताई गई है।","Lava.":"Lava।","Новые международные покупки в текущем выпуске выключены; новые российские заказы туда не передаются.":"नई अंतरराष्ट्रीय खरीद इस रिलीज़ में बंद है; नए रूसी ऑर्डर वहाँ नहीं भेजे जाते।","Ранее оформленные заказы и сведения, необходимые для их исполнения или возврата, регулируются условиями соответствующего заказа.":"पुराने ऑर्डर और उन्हें पूरा या वापस करने का डेटा उस ऑर्डर की शर्तों पर चलता है।","При российской покупке передаются необходимые сведения о заказе: почта, продукт, сумма, валюта и срок.":"रूसी खरीद में आवश्यक ईमेल, उत्पाद, राशि, मुद्रा और अवधि भेजी जाती है।","Сервис возвращает подтверждённый статус платежа.":"सेवा पुष्ट भुगतान स्थिति लौटाती है।","В текущем выпуске покупка оформляется из приложения.":"इस रिलीज़ में खरीद ऐप में होती है।","На сайте нет работающей формы входа или оплаты, и новые токены аккаунта через сайт не запрашиваются.":"वेबसाइट पर चालू प्रवेश या भुगतान फ़ॉर्म नहीं हैं, न नए खाता टोकन माँगे जाते हैं।","Если в браузере сохранился сеанс прежней международной страницы, его можно удалить в настройках данных сайта.":"पुराने अंतरराष्ट्रीय पेज का सत्र ब्राउज़र में बचा हो तो वेबसाइट डेटा सेटिंग से मिटाएँ।","Прежняя версия хранения сеанса описана в архивной политике.":"पुराने सत्र भंडारण का विवरण संग्रहित नीति में है।","Удаление данных приложения удаляет локальный прогресс и настройки, но само по себе не удаляет серверный аккаунт, уже переданный облачный прогресс или сведения о покупке.":"ऐप डेटा मिटाने से स्थानीय प्रगति और सेटिंग हटती हैं, सर्वर खाता, भेजी क्लाउड प्रगति या खरीद नहीं।","Для восстановления нужно снова войти в тот же аккаунт.":"बहाल करने के लिए फिर उसी खाते में प्रवेश करें।","Временные счётчики защиты имеют срок от минуты до двух суток, в том числе до часа для ограничения запросов с одного IP-адреса.":"अस्थायी सुरक्षा गणक एक मिनट से दो दिन तक, और एक IP सीमित करने हेतु एक घंटे तक रहते हैं।","Подтверждённый аккаунт, поддерживаемый облачный прогресс и история заказов автоматически не удаляются при окончании Plus.":"Plus समाप्त होने पर सत्यापित खाता, समर्थित क्लाउड प्रगति और ऑर्डर इतिहास अपने-आप नहीं मिटते।","Продление для хранения и восстановления прогресса не требуется.":"प्रगति रखने और बहाल करने के लिए नवीनीकरण नहीं चाहिए।","Для изученных ключей не задаётся автоматический срок удаления из-за окончания подписки; это не отменяет право на удаление по запросу.":"सदस्यता समाप्ति के कारण सीखे मूल घटकों की स्वतः-मिटने की अवधि नहीं है; अनुरोध पर हटाने का अधिकार रहता है।",", тема: «Удаление аккаунта Hanzi». Укажи, что нужно удалить серверный аккаунт.":", विषय: «Hanzi खाता हटाएँ»। बताएँ कि सर्वर खाता मिटाना है।","Удаление аккаунта включает удаление его облачного прогресса Bloom и Keys и прекращает возможность входа и восстановления Plus через него; перед удалением действующей покупки можно отдельно обсудить отказ от услуги и возврат по":"खाता हटाने में Bloom और Keys की क्लाउड प्रगति भी हटती है तथा प्रवेश और Plus बहाली बंद होती है; सक्रिय खरीद हटाने से पहले छोड़ने और वापसी पर अलग चर्चा हो सकती है, इसके अनुसार:",". Другие сохранённые редакции доступны по запросу в поддержку.":"। अन्य सहेजे संस्करण सहायता से माँग सकते हैं।","Explore app":"ऐप देखें","Translation for convenience. Original document: {language}.":"सुविधा के लिए अनुवाद। मूल दस्तावेज़ की भाषा: {language}।","Show original document":"मूल दस्तावेज़ दिखाएँ","Language":"भाषा","Choose your language":"अपनी भाषा चुनें","Search languages":"भाषाएँ खोजें","Close language selection":"भाषा सूची बंद करें","Language changed to {language}":"भाषा {language} कर दी गई","The page language does not change your payment region or currency.":"पेज की भाषा भुगतान क्षेत्र या मुद्रा नहीं बदलती।","No languages found":"कोई भाषा नहीं मिली","Use device language":"उपकरण की भाषा उपयोग करें","PERFECT KICK":"शानदार छलाँग!","{v0} · {v1}":"{v0} · {v1}","{v0} — {v1}. Found!":"{v0} — {v1}. मिल गया!","{v0} — {v1}. Ключ найден!":"{v0} — {v1}. मिल गया!","{v0} · {v1} servings":"{v0} · {v1} सर्विंग","{v0} · {v1} порц.":"{v0} · {v1} सर्विंग","{v0} — {v1} pcs":"{v0} — {v1} नग","{v0} — {v1} шт.":"{v0} — {v1} नग","{v0} — {v1} g":"{v0} — {v1} g","{v0} — {v1} г":"{v0} — {v1} g","Новый код · {seconds} с":"नया कोड · {seconds} सेकंड","· {v0} servings":"· {v0} सर्विंग","· {v0} порц.":"· {v0} सर्विंग","{remaining} left · {done} done":"{remaining} बाकी · {done} पूरे","Finish · {count} bought":"समाप्त करें · {count} खरीदे","{remaining} осталось · {done} готово":"{remaining} बाकी · {done} पूरे","Куплено: {count} · завершить":"समाप्त करें · {count} खरीदे"},overrides);Object.assign(window.HANZI_SOURCE_ALIASES||{},{"मुख्य सामग्री पर जाएँ":"Skip to content","पिछला स्क्रीनशॉट":"Previous screenshot","अगला स्क्रीनशॉट":"Next screenshot","सार्वजनिक प्रस्ताव":"Оферта","Plus प्लान":"Тарифы Plus","16 अक्टूबर 2026 के प्रथम संस्करण का संग्रह।":"Архив первой редакции от 16 октября 2026 года.","वर्तमान संस्करण":"Действующая редакция","पिछला संस्करण:":"Предыдущая редакция:","8 अक्टूबर 2026":"8 октября 2026 года","खाता और पहुँच":"Аккаунт и доступ","आपका डेटा · साफ़ नियम":"Твои данные · понятные правила","गोपनीयता नीति":"Политика конфиденциальности","विषय-सूची":"Содержание","डेटा कौन संसाधित करता है":"Кто обрабатывает","कौन-सा डेटा":"Какие данные","बाहरी सेवाएँ":"Внешние сервисы","अवधियाँ":"Сроки","हटाना और अधिकार":"Удаление и права","1. डेटा का उत्तरदायी कौन है":"1. Кто отвечает за данные","नियंत्रक: Anastasia Maksimovna Pokamestova, स्व-नियोजित (पेशेवर आय कर), कर पहचान संख्या 695205887530, Tver।":"Оператор: Покаместова Анастасия Максимовна, самозанятая (НПД), ИНН 695205887530, город Тверь.","Raccoon App Labs डेवलपर का नाम है।":"Raccoon App Labs — название разработчика.","डेटा संबंधी संपर्क:":"Контакт по вопросам данных:",", फ़ोन":", телефон","यह स्वतंत्र भुगतान, ईमेल और सिस्टम सेवाओं के नियमों का विकल्प नहीं।":"Она не заменяет правила самостоятельных платёжных, почтовых и системных сервисов.","2. कौन-सा डेटा और क्यों":"2. Какие данные и для чего","अध्ययन प्रगति":"Прогресс обучения","खाता और प्रवेश":"Аккаунт и вход","ईमेल, यादृच्छिक खाता पहचान, ईमेल सत्यापन और कोड अनुरोध तथा जाँच की तारीखें।":"Адрес электронной почты, случайный идентификатор аккаунта, подтверждение почты, даты запросов и проверки кода.","सर्वर एकबारगी कोड और सत्र टोकन के हैश रखता है।":"На сервере хранятся хеши одноразовых кодов и токенов сессий.","इनसे प्रवेश, ऑर्डर स्वामी की जाँच और सशुल्क पहुँच की बहाली होती है।":"Они нужны для входа, проверки владельца заказа и восстановления оплаченного доступа.","खरीद और Plus":"Покупка и Plus","खाते का ईमेल, ऑर्डर संख्या और स्थिति, उत्पाद तथा प्रस्ताव पहचान, राशि, मुद्रा, अवधि, भुगतान बनाने और पुष्टि की तारीखें, स्वीकृत संस्करण, पहुँच समाप्ति और वापसी या विवाद विवरण।":"Почта аккаунта, номер и статус заказа, идентификаторы продукта и предложения, сумма и валюта, выбранный срок, даты создания и подтверждения платежа, версия принятой оферты, дата окончания доступа, сведения о возврате или споре.","बनाया ऑर्डर जारी रखने के लिए भुगतान लिंक रखा जाता है।":"Ссылка на оплату хранится для продолжения созданного заказа.","सुरक्षा और वेबसाइट संचालन":"Безопасность и работа сайта","कनेक्ट करते समय अवसंरचना को IP और तकनीकी कनेक्शन विवरण उपलब्ध होते हैं।":"IP-адрес и технические параметры соединения доступны инфраструктуре при обращении к ней.","प्रवेश अनुरोध सीमित करने के लिए सर्वर IP हैश और अनुरोध गणक उपयोग करता है।":"Для ограничения запросов входа сервер приложения использует хеш IP-адреса и счётчики запросов.","इससे कोड का अनुमान लगाने और सामूहिक अनुरोध रोकने में मदद मिलती है।":"Это помогает предотвратить подбор кодов и массовые запросы.","सहायता अनुरोध":"Обращение в поддержку","आपका ईमेल और भेजा संदेश, स्वेच्छा से जुड़ी फ़ाइलों तथा ऑर्डर विवरण सहित।":"Твоя почта и содержание присланного обращения, включая добровольно приложенные файлы и сведения о заказе.","इनका उपयोग उत्तर, पहुँच बहाली या धनवापसी के लिए होता है।":"Используем их, чтобы ответить, восстановить доступ или обработать возврат.","कार्ड विवरण, बैंक कोड या ईमेल पासवर्ड न भेजें।":"Не присылай реквизиты карты, банковские коды и пароль от почты.","ऐप विश्लेषण":"Аналитика приложения","MyTracker शुरुआत, सत्र, स्क्रीन बदलाव और अभ्यास घटनाएँ तथा SDK का तकनीकी डेटा पाता है: ऐप और सिस्टम संस्करण, उपकरण मापदंड, नेटवर्क और उपलब्ध उपकरण पहचान।":"MyTracker получает события запуска, сессий, переходов между экранами и выполнения упражнений, а также технические сведения SDK: версию приложения и системы, параметры устройства, сетевые и доступные устройству идентификаторы.","विज्ञापन":"Реклама","Yandex Mobile Ads विज्ञापन दिखाने और अमान्य ट्रैफ़िक रोकने के लिए उपकरण, कनेक्शन, विज्ञापन पहचान और दृश्य संबंधी तकनीकी डेटा उपयोग करता है।":"Yandex Mobile Ads использует технические данные устройства, соединения, рекламные идентификаторы и сведения о показах для работы рекламы и защиты от недействительного трафика.","ऐप सेटिंग में विज्ञापन हेतु स्थान भेजना बंद है।":"Передача геолокации для рекламы отключена настройкой приложения.","Hanzi Bloom की सेटिंग से वैयक्तिकरण नियंत्रित होता है; बंद करने पर भी विज्ञापन दिखाने का तकनीकी प्रसंस्करण रह सकता है।":"Персонализация управляется переключателем в настройках Hanzi Bloom; при выключенной персонализации техническая обработка для показа рекламы может сохраняться.","बोलने और लिखने का अभ्यास":"Голосовая и рукописная практика","चुने मौखिक अभ्यास के लिए Android अनुमति के बाद माइक्रोफ़ोन चालू होता है।":"Микрофон включается для выбранного тобой голосового упражнения после разрешения Android.","सिस्टम की वाणी पहचान सेवा उपकरण और चुनी सेवा के अनुसार अपने सर्वर पर आवाज़ संसाधित कर सकती है।":"Системная служба распознавания речи может обрабатывать звук на своих серверах в зависимости от устройства и выбранного сервиса.","Hanzi Bloom खाता सर्वर को ऑडियो रिकॉर्डिंग नहीं मिलती।":"Сервер аккаунта Hanzi Bloom аудиозаписи не получает.","हस्तलिखित स्ट्रोक की पहचान उपकरण पर होती है; मॉडल आपूर्तिकर्ता की सेवा से डाउनलोड हो सकते हैं।":"Распознавание рукописных штрихов выполняется на устройстве; модели могут загружаться через сервис их поставщика.","उपयोगकर्ता वर्ग: वेबसाइट आगंतुक, ऐप और खाता उपयोगकर्ता, Plus खरीदार और सहायता से संपर्क करने वाले।":"Категории пользователей: посетители сайта, пользователи приложения и аккаунта, покупатели Plus и обратившиеся в поддержку.","खाता या खरीद के लिए विशेष डेटा वर्ग और बायोमेट्रिक पहचान का उपयोग नहीं होता।":"Специальные категории данных и биометрическая идентификация для аккаунта и покупки не используются.","3. प्रसंस्करण के आधार और तरीके":"3. Основания и способы обработки","ईमेल, खाता और ऑर्डर डेटा उपयोगकर्ता के अनुरोध और अनुबंध पूरा करने के लिए आवश्यक हैं।":"Почта, данные аккаунта и заказа нужны для действий по запросу пользователя и исполнения договора.","भुगतान रिकॉर्ड अनिवार्य कानूनी जरूरतों के लिए भी रखे जाते हैं।":"Данные расчётов сохраняются также для обязательных требований закона.","उचित कानूनी आधार होने पर तकनीकी डेटा सुरक्षा और सुधार के लिए उपयोग होता है।":"Технические данные используются для безопасности и улучшения приложения при наличии применимого правового основания.","आवश्यक सहमति अलग ली जाती है; यह नीति विज्ञापन या असीमित डेटा हस्तांतरण की सहमति नहीं।":"Когда необходимо согласие, оно должно оформляться отдельно; эта политика не является согласием на рассылку или на неограниченную передачу данных.","प्रसंस्करण स्वचालित और अनुरोधों में मानव द्वारा भी होता है: संग्रह, भंडारण, जाँच, उपयोग, आवश्यक सेवाओं को देना, सुधार और हटाना।":"Обработка автоматизированная, а при обращениях — также с участием оператора: сбор, хранение, проверка, использование, предоставление необходимым сервисам, исправление и удаление.","व्यक्तिगत खाता डेटा प्रकाशित या बेचा नहीं जाता।":"Персональные данные аккаунта не публикуются и не продаются.","प्रवेश ईमेल कोड और सेवा संदेशों के लिए है, विज्ञापन के लिए नहीं।":"Почта входа используется для кодов и сообщений по услуге, а не для рекламной рассылки.","4. डेटा कहाँ संसाधित होता है":"4. Где обрабатываются данные","Google / Gmail।":"Google / Gmail.","ईमेल पहुँचाने के लिए पता और कोड मेल सेवा को दिए जाते हैं। सहायता अनुरोध Gmail में देखे जाते हैं।":"Почта и код входа передаются почтовому сервису для доставки письма. Обращения поддержки обрабатываются в Gmail.","Google नीति":"Политика Google","Lava नीति":"Политика Lava","Robokassa।":"Robokassa.","उपलब्ध रूसी भुगतान विकल्प चुनने पर यह सेवा ऑर्डर डेटा संसाधित करती है।":"При выборе доступного российского способа оплаты данные заказа обрабатываются этим сервисом.","Robokassa नीति":"Политика Robokassa","GitHub Pages।":"GitHub Pages.","सार्वजनिक पेज होस्ट करता और तकनीकी विज़िट डेटा पाता है। खाता और ऑर्डर डेटाबेस रिपॉज़िटरी में नहीं है।":"Размещает публичные страницы сайта и получает технические данные посещений. База аккаунтов и заказов не размещается в репозитории.","GitHub नीति":"Политика GitHub","MyTracker (VK) और Yandex Mobile Ads।":"MyTracker (VK) и Yandex Mobile Ads.","इन SDK वाले संस्करणों में ऊपर वर्णित विश्लेषण और विज्ञापन डेटा मिलता है।":"Получают данные аналитики и рекламы, описанные выше, в версиях приложения с этими SDK.","MyTracker नीति":"Политика MyTracker","Yandex नीति":"политика Яндекса","Google, GitHub, Lava और सिस्टम वाणी पहचान रूस के बाहर डेटा संसाधित कर सकते हैं; Lava अपनी कंपनी का स्थान साइप्रस बताता है।":"Google, GitHub, Lava и системная служба распознавания могут обрабатывать сведения за пределами России; Lava указывает Кипр как место нахождения своей компании.","रूस में खाता डेटाबेस होने का अर्थ सभी सेवाओं का केवल रूस में चलना नहीं।":"Российское размещение базы аккаунтов не означает, что все перечисленные сервисы работают только в России.","अंतरराष्ट्रीय हस्तांतरण के लिए अलग कानूनी आधार और प्रक्रियाएँ चाहिए; नीति प्रकाशित करना उनका विकल्प नहीं।":"Международная передача требует самостоятельного применимого основания и соблюдения установленных законом процедур; публикация политики их не заменяет.","5. ब्राउज़र और उपकरण भंडारण":"5. Хранение в браузере и на устройстве","खरीद पेज पर विज्ञापन या विश्लेषण ट्रैकर नहीं हैं।":"На странице покупки не установлены рекламные или аналитические счётчики.","GitHub अवसंरचना और बाहरी भुगतान पेज के अपने भंडारण और कुकी नियम हैं।":"Инфраструктура GitHub и страницы внешних платёжных сервисов имеют собственные правила технического хранения и cookie.","ऐप का खाता टोकन Android Keystore से एन्क्रिप्ट है और सिस्टम बैकअप में नहीं जाता।":"В приложении токен аккаунта хранится с шифрованием через Android Keystore и исключён из системной резервной копии.","6. अवधि और सुरक्षा":"6. Сроки и защита","प्रवेश कोड 10 मिनट; सत्र अधिकतम 30 दिन रहता है और पुष्ट साइन आउट पर पहले समाप्त होता है।":"Код входа действует 10 минут; сессия — до 30 дней и прекращается раньше после подтверждённого выхода.","असत्यापित खाता अधिकतम 24 घंटे रखा जाता है।":"Неподтверждённый аккаунт хранится до 24 часов.","समाप्ति पर उपयोग रुकता है; डेटाबेस अस्थायी रिकॉर्ड बाद में भौतिक रूप से हटा सकता है।":"Истечение срока исключает их использование; физическое удаление временных записей выполняется механизмом базы данных и может происходить позднее.","पहुँच बहाल करने के लिए जरूरत तक खाता रहता है; हटाने के नियम अगले अनुभाग में हैं।":"Аккаунт хранится для восстановления доступа, пока он нужен пользователю; удаление запрашивается по правилам следующего раздела.","भुगतान और अनुरोध डेटा अनुबंध, वापसी, विवाद और अनिवार्य लेखांकन के लिए जरूरी अवधि तक रहता है, फिर मिटता या अनाम किया जाता है।":"Данные платежей и обращений сохраняются только на срок, необходимый для исполнения обязательств, возвратов, разрешения споров и обязательного учёта, затем удаляются или обезличиваются.","अनिवार्य रिकॉर्ड खाता मिटने के बाद भी रह सकते हैं।":"Обязательные записи могут сохраняться после удаления аккаунта.","सर्वर कनेक्शन HTTPS से सुरक्षित है।":"Соединение с сервером защищено HTTPS.","अनुरोध सीमाएँ, ऑर्डर स्वामी सत्यापन, अवसंरचना पहुँच नियंत्रण और खुले कोड तथा टोकन के बजाय हैश उपयोग होते हैं।":"Применяются ограничение запросов, проверка принадлежности заказа, контроль доступа к инфраструктуре и хранение хешей вместо открытых кодов и серверных токенов.","अपना प्रवेश कोड किसी को न दें।":"Не передавай другим людям код входа.","केवल «सफलता» पेज का पता भुगतान या सक्रियण का प्रमाण नहीं; सर्वर सेवा की सूचना और विवरण जाँचता है।":"Оплата и активация не подтверждаются одним только адресом страницы «успех»: сервер проверяет уведомление и сведения платёжного сервиса.","7. डेटा सुधारना और हटाना":"7. Уточнение и удаление данных","खाता मिटाना चाहते हैं?":"Хочешь удалить аккаунт?","खाते वाले ईमेल से लिखें":"Напиши с почты аккаунта на","अपने डेटा की जानकारी, सुधार, रोक या हटाने का अनुरोध और सहमति आधारित प्रसंस्करण की सहमति वापस ले सकते हैं।":"Можно запросить сведения об обработке своих данных, исправление, блокирование или удаление, а также отозвать согласие, если обработка основана на нём.","खाते की रक्षा हेतु नियंत्रक स्वामी की पहचान जाँचता है।":"Для защиты аккаунта оператор проверяет, что обращается его владелец.","अनुरोध के लिए कार्ड, CVC या प्रवेश कोड नहीं चाहिए।":"Карта, CVC и код входа для обращения не нужны.","कानून कुछ रिकॉर्ड रखना माँगे तो उत्तर में बताया जाता है।":"Если сохранить часть записей требует закон, сообщаем об этом при ответе.","अनुरोध लागू कानूनी समयसीमा में देखे जाते हैं।":"Обращения рассматриваются в применимые законные сроки.","प्रस्ताव":"оферте","स्थानीय प्रगति Android या ऐप सेटिंग से हटती है।":"Удаление локального прогресса выполняется через настройки Android или приложения.","स्वतंत्र बाहरी सेवाओं को ऊपर जुड़ी उनकी नीतियों के अनुसार अनुरोध भेज सकते हैं।":"Запросы к самостоятельным внешним сервисам можно направлять им по указанным выше политикам.","डेटा सुरक्षा के लिए नियंत्रक, अधिकृत प्राधिकरण Roskomnadzor या अदालत से संपर्क कर सकते हैं।":"По вопросам защиты персональных данных можно обратиться к оператору, а также в уполномоченный орган — Роскомнадзор — или в суд.","8. बच्चे और नीति बदलाव":"8. Дети и изменения политики","खरीद खाता कानूनी रूप से सक्षम खरीदार उपयोग करता है; आवश्यकता पर कानूनी प्रतिनिधि खरीदता है।":"Аккаунт для покупки используется дееспособным покупателем; при необходимости покупку совершает законный представитель.","प्रतिनिधि बच्चे के डेटा पर नियंत्रक से संपर्क कर सकता है।":"В обращении о данных ребёнка представитель может связаться с оператором.","खरीद के लिए जन्मतिथि नहीं माँगी जाती।":"Приложение не запрашивает дату рождения для покупки.","नया संस्करण बदलाव की तारीख सहित इसी पते पर प्रकाशित होता है।":"Новая редакция публикуется по этому адресу с датой изменения.","अलग सहमति जरूरी होने वाले उद्देश्य या डेटा वर्ग बदलें तो पाठ अपडेट करना सहमति का विकल्प नहीं।":"Если меняются цели или состав обработки, для которых необходимо отдельное согласие, обновление текста само по себе его не заменяет.","सहायता":"Поддержка","Hanzi Bloom और Hanzi Keys के डेटा: प्रगति, खाता, भुगतान, विश्लेषण और विज्ञापन। खाता हटाने का अनुरोध कैसे करें।":"Какие данные используют Hanzi Bloom и Hanzi Keys: прогресс, аккаунт, оплата, аналитика и реклама. Как запросить удаление аккаунта.","गोपनीयता · Hanzi Bloom और Hanzi Keys":"Конфиденциальность · Hanzi Bloom и Hanzi Keys","व्यक्तिगत डेटा प्रसंस्करण नीति। 16 अक्टूबर 2026 का संस्करण।":"Политика обработки персональных данных. Редакция от 16 октября 2026 года.","Bloom और Keys के लिए एक खाता।":"Один аккаунт для Bloom и Keys.","ईमेल प्रवेश और साझा Plus बहाली के लिए है।":"Почта нужна для входа и восстановления общего Plus.","पहली सदस्यता के बाद समर्थित प्रगति सशुल्क अवधि खत्म होने पर भी खाते में रहती है।":"После первой подписки поддерживаемый прогресс сохраняется в аккаунте и после окончания оплаченного срока.","कार्ड विवरण Robokassa में डालते हैं।":"Данные карты вводятся у Робокассы.","सहायता से खाता और क्लाउड डेटा हटाने को कह सकते हैं।":"Удаление аккаунта и облачных данных можно запросить в поддержку.","नीति Android के Hanzi Bloom, Hanzi Keys, उनके साझा Hanzi Plus खाते और raccoon-app-labs.github.io के पेजों पर लागू है।":"Политика относится к Android-приложениям Hanzi Bloom и Hanzi Keys, их общему аккаунту Hanzi Plus и страницам этих приложений на raccoon-app-labs.github.io.","प्रगति और सेटिंग उपकरण पर रहती हैं।":"Прогресс и настройки сохраняются на устройстве.","कम-से-कम एक बार उत्पादन Plus पाने वाले सत्यापित खाते में समर्थित प्रगति सर्वर से भी सिंक होती है।":"Для подтверждённого аккаунта, хотя бы раз получившего производственную подписку Plus, поддерживаемый прогресс также синхронизируется с сервером.","Keys केवल सीखे मूल घटकों की ID भेजता है; अनसीखे कार्ड और कैटलॉग पाठ कॉपी नहीं होते।":"Keys передаёт только ID изученных ключей; неизученные карточки и тексты каталога не копируются.","Bloom अध्ययन शब्दों और अक्षरों की ID तथा स्थिति, पूरे पाठों की ID, अंतिम पाठ, स्तर और अध्याय जाँच के सर्वोत्तम परिणाम भेजता है।":"Bloom передаёт ID и статусы изучаемых слов и иероглифов, ID завершённых уроков, последний урок, достигнутый уровень курса и лучшие результаты проверок глав.","हर ऐप के क्लाउड रिकॉर्ड अलग हैं और खाते के हैं।":"Облачные записи приложений раздельны и принадлежат аккаунту.","इस क्लाउड प्रति में निजी नोट्स, ऑडियो, चित्र, पूरी अभ्यास-इतिहास और स्थानीय पुनरावृत्ति अंतराल नहीं हैं।":"Личные заметки, аудио, рисунки, полная история упражнений и локальные интервалы повторений в эту облачную копию не входят.","समर्थित संस्करण, प्रवेश और इंटरनेट चाहिए।":"Нужны поддерживающая версия, вход и Интернет.","मुफ़्त सप्ताह और परीक्षण भुगतान क्लाउड नहीं खोलते।":"Бесплатная неделя и тестовые платежи не включают облако.","Hanzi सर्वर को पूरा कार्ड नंबर, CVC और बैंक कोड नहीं मिलते।":"Полный номер карты, CVC и банковские коды сервер Hanzi не получает.","Keys का परिचय सप्ताह":"Неделя знакомства Keys","यादृच्छिक इंस्टॉल कुंजी उपकरण पर रहती है; सर्वर उसका हैश, मुफ़्त अवधि की शुरुआत और पहले Plus मिलने का संकेत उपयोग करता है।":"Случайный ключ установки хранится на устройстве; сервер использует его хеш, дату начала бесплатного периода и признак ранее предоставленного Plus.","प्रवेश पर अवधि का इतिहास खाते से भी जुड़ता है।":"При входе история периода связывается также с аккаунтом.","यह परिचय अवधि और पहुँच जाँचने के लिए है, उपकरण की सामग्री से पहचानने के लिए नहीं।":"Это нужно для расчёта срока знакомства и проверки доступа, а не для идентификации по содержимому устройства.","निजी ऐप घटनाओं में खोज, अपने शब्द, अनुवाद, कहानी, हस्तलिखित स्ट्रोक, ईमेल या टोकन नहीं जुड़ते।":"В пользовательские события приложений не добавляются текст поиска, свои слова, переводы, тексты историй, рукописные штрихи, почта аккаунта или токен входа.","Hanzi की रूसी सर्वर अवसंरचना।":"Российская серверная инфраструктура Hanzi.","रूसी क्षेत्र के खाते, सदस्यताएँ, ऑर्डर और समर्थित क्लाउड प्रगति api1.hanzibloom.ru के रूसी भंडारण में संसाधित होते हैं।":"Аккаунты российского региона, подписки, заказы и поддерживаемый облачный прогресс обрабатываются через api1.hanzibloom.ru в российском серверном хранилище.","अलग उपयोगकर्ताओं के खाते और प्रगति अलग हैं।":"Аккаунты и прогресс разных пользователей разделены.","डेटाबेस सार्वजनिक GitHub रिपॉज़िटरी में नहीं है।":"База не размещается в публичном репозитории GitHub.","पुरानी Yandex Cloud होस्टिंग संग्रहित नीति में बताई गई है।":"Прежнее размещение Yandex Cloud описано в архивной редакции политики.","Lava।":"Lava.","नई अंतरराष्ट्रीय खरीद इस रिलीज़ में बंद है; नए रूसी ऑर्डर वहाँ नहीं भेजे जाते।":"Новые международные покупки в текущем выпуске выключены; новые российские заказы туда не передаются.","पुराने ऑर्डर और उन्हें पूरा या वापस करने का डेटा उस ऑर्डर की शर्तों पर चलता है।":"Ранее оформленные заказы и сведения, необходимые для их исполнения или возврата, регулируются условиями соответствующего заказа.","रूसी खरीद में आवश्यक ईमेल, उत्पाद, राशि, मुद्रा और अवधि भेजी जाती है।":"При российской покупке передаются необходимые сведения о заказе: почта, продукт, сумма, валюта и срок.","सेवा पुष्ट भुगतान स्थिति लौटाती है।":"Сервис возвращает подтверждённый статус платежа.","इस रिलीज़ में खरीद ऐप में होती है।":"В текущем выпуске покупка оформляется из приложения.","वेबसाइट पर चालू प्रवेश या भुगतान फ़ॉर्म नहीं हैं, न नए खाता टोकन माँगे जाते हैं।":"На сайте нет работающей формы входа или оплаты, и новые токены аккаунта через сайт не запрашиваются.","पुराने अंतरराष्ट्रीय पेज का सत्र ब्राउज़र में बचा हो तो वेबसाइट डेटा सेटिंग से मिटाएँ।":"Если в браузере сохранился сеанс прежней международной страницы, его можно удалить в настройках данных сайта.","पुराने सत्र भंडारण का विवरण संग्रहित नीति में है।":"Прежняя версия хранения сеанса описана в архивной политике.","ऐप डेटा मिटाने से स्थानीय प्रगति और सेटिंग हटती हैं, सर्वर खाता, भेजी क्लाउड प्रगति या खरीद नहीं।":"Удаление данных приложения удаляет локальный прогресс и настройки, но само по себе не удаляет серверный аккаунт, уже переданный облачный прогресс или сведения о покупке.","बहाल करने के लिए फिर उसी खाते में प्रवेश करें।":"Для восстановления нужно снова войти в тот же аккаунт.","अस्थायी सुरक्षा गणक एक मिनट से दो दिन तक, और एक IP सीमित करने हेतु एक घंटे तक रहते हैं।":"Временные счётчики защиты имеют срок от минуты до двух суток, в том числе до часа для ограничения запросов с одного IP-адреса.","Plus समाप्त होने पर सत्यापित खाता, समर्थित क्लाउड प्रगति और ऑर्डर इतिहास अपने-आप नहीं मिटते।":"Подтверждённый аккаунт, поддерживаемый облачный прогресс и история заказов автоматически не удаляются при окончании Plus.","प्रगति रखने और बहाल करने के लिए नवीनीकरण नहीं चाहिए।":"Продление для хранения и восстановления прогресса не требуется.","सदस्यता समाप्ति के कारण सीखे मूल घटकों की स्वतः-मिटने की अवधि नहीं है; अनुरोध पर हटाने का अधिकार रहता है।":"Для изученных ключей не задаётся автоматический срок удаления из-за окончания подписки; это не отменяет право на удаление по запросу.",", विषय: «Hanzi खाता हटाएँ»। बताएँ कि सर्वर खाता मिटाना है।":", тема: «Удаление аккаунта Hanzi». Укажи, что нужно удалить серверный аккаунт.","खाता हटाने में Bloom और Keys की क्लाउड प्रगति भी हटती है तथा प्रवेश और Plus बहाली बंद होती है; सक्रिय खरीद हटाने से पहले छोड़ने और वापसी पर अलग चर्चा हो सकती है, इसके अनुसार:":"Удаление аккаунта включает удаление его облачного прогресса Bloom и Keys и прекращает возможность входа и восстановления Plus через него; перед удалением действующей покупки можно отдельно обсудить отказ от услуги и возврат по","। अन्य सहेजे संस्करण सहायता से माँग सकते हैं।":". Другие сохранённые редакции доступны по запросу в поддержку.","ऐप देखें":"Explore app","सुविधा के लिए अनुवाद। मूल दस्तावेज़ की भाषा: {language}।":"Translation for convenience. Original document: {language}.","मूल दस्तावेज़ दिखाएँ":"Show original document","भाषा":"Language","अपनी भाषा चुनें":"Choose your language","भाषाएँ खोजें":"Search languages","भाषा सूची बंद करें":"Close language selection","भाषा {language} कर दी गई":"Language changed to {language}","पेज की भाषा भुगतान क्षेत्र या मुद्रा नहीं बदलती।":"The page language does not change your payment region or currency.","कोई भाषा नहीं मिली":"No languages found","उपकरण की भाषा उपयोग करें":"Use device language","शानदार छलाँग!":"PERFECT KICK","{v0} — {v1}. मिल गया!":"{v0} — {v1}. Found!","{v0} · {v1} सर्विंग":"{v0} · {v1} servings","{v0} — {v1} नग":"{v0} — {v1} pcs","नया कोड · {seconds} सेकंड":"Новый код · {seconds} с","· {v0} सर्विंग":"· {v0} servings","{remaining} बाकी · {done} पूरे":"{remaining} left · {done} done","समाप्त करें · {count} खरीदे":"Finish · {count} bought"});})();
